% runCase1c  Case 1(c), one-way mechanistic chain (myxomatosis). GeoC, invariant density, overview figure and density error.
%
% CALLS     generateCase1Series, dwyerBeta, estimateGeoC, estimateInvariantDensity2D, batlow, addPanelLabel
% INPUT     none (the record is generated by generateCase1Series('1c'))
% OUTPUT    ResultsCase1c/Figure_Case1c_Overview.png, Case1c_GeoC_summary.csv and the GeoC table printed in the command window

clear; close all; clc;
set(groot, 'defaultTextInterpreter', 'latex');
set(groot, 'defaultAxesTickLabelInterpreter', 'latex');
set(groot, 'defaultLegendInterpreter', 'latex');
set(groot, 'defaultAxesFontName', 'Helvetica');
set(groot, 'defaultTextFontName', 'Helvetica');

outDir = 'ResultsCase1c';
if ~exist(outDir, 'dir'), mkdir(outDir); end

%%
a = 2.0; b = 4.0; c = 10.0; q0 = -1.48; q1 = 0.293; delta = 0.01;
[Mu, Beta] = generateCase1Series('1c');

x_grid = linspace(1e-4, 1-1e-4, 20000)';
denom = x_grid.^a + c.*(1-x_grid).^b;
h_grid = (x_grid.^a) ./ denom;
dh_dx = c.*x_grid.^(a-1).*(1-x_grid).^(b-1).*(a.*(1-x_grid) + b.*x_grid) ./ (denom.^2);
p_exact = (1 ./ (pi.*sqrt(h_grid.*(1-h_grid)))) .* abs(dh_dx);
p_exact = p_exact ./ trapz(x_grid, p_exact);

%%
d2Opts = {'MinPlateauLength', 10, 'SlopeCVmax', 0.15, 'MaxSlopeDrift', 0.10, 'R2min', 0.98, 'Cmax', 0.20, 'MinPairs', 1000};
[T, details] = estimateGeoC(Mu, Beta, 'Subsample', 2500, 'Seed', 3, d2Opts{:});
disp(T);

geo_mu_self = details.D2_mun_munp1.D2 - details.D2_mun.D2;
geo_beta_self = details.D2_betan_betanp1.D2 - details.D2_betan.D2;
geo_mu_cond = details.D2_mun_betan_munp1.D2 - details.D2_mun_betan.D2;
geo_beta_cond = details.D2_betan_mun_betanp1.D2 - details.D2_betan_mun.D2;
geo_beta_to_mu = geo_mu_self - geo_mu_cond;
geo_mu_to_beta = geo_beta_self - geo_beta_cond;

invOut = estimateInvariantDensity2D(Mu, Beta, 'NBins', 100, 'Bounds', [0, 0; 1, max(Beta)]);

%%
mu_map = linspace(max(1e-4, min(Mu)), min(0.9999, max(Mu)), 500)';
k1_map = 3.68 - 7.8.*mu_map + 7.5.*mu_map.^2;
k2_map = 0.265 - 0.66.*mu_map + 0.56.*mu_map.^2;
T_map = 334.7 - 70.3.*log(100.*mu_map);
beta_map = max(arrayfun(@(m) dwyerBeta(m, delta, q0, q1), mu_map), 0);
normalize01 = @(x) (x - min(x)) ./ max(max(x) - min(x), eps);

fig = figure('Color', 'w', 'Units', 'centimeters', 'Position', [2, 2, 18, 13]);
tl = tiledlayout(fig, 2, 2, 'TileSpacing', 'compact', 'Padding', 'compact');

axA = nexttile(tl, 1);
hold(axA, 'on');
h1 = plot(axA, mu_map, normalize01(k1_map), '-', 'Color', [0.15 0.15 0.15], 'LineWidth', 1.5);
h2 = plot(axA, mu_map, normalize01(k2_map), '--', 'Color', [0.40 0.40 0.40], 'LineWidth', 1.5);
h3 = plot(axA, mu_map, normalize01(T_map), '-.', 'Color', [0.62 0.62 0.62], 'LineWidth', 1.5);
h4 = plot(axA, mu_map, normalize01(beta_map), '-', 'Color', [0.00 0.32 0.58], 'LineWidth', 2.0);
hold(axA, 'off');
xlabel(axA, 'Virulence, $\mu$');
ylabel(axA, 'Normalized response');
legend(axA, [h1 h2 h3 h4], {'$k_1(\mu)$', '$k_2(\mu)$', '$T(\mu)$', '$\beta(\mu)$'}, 'Location', 'best', 'Box', 'off', 'FontSize', 7.5);
xlim(axA, [mu_map(1) mu_map(end)]); ylim(axA, [-0.03 1.05]);
title(axA, 'Empirical virulence-dependent mapping', 'FontWeight', 'normal', 'FontSize', 10);
addPanelLabel(axA, '(a)', -0.10, 1.04, 11);
styleMainAxis(axA);

axB = nexttile(tl, 2);
hold(axB, 'on');
Rs = {details.D2_betan, details.D2_betan_betanp1};
cols = {[0.12 0.31 0.89], [0.85 0.15 0.20]};
marks = {'o-', 's-'};
alphas = [0.08, 0.07];
hB = gobjects(1, 2);
slopeValues = [];
for k = 1:2
    R = Rs{k};
    rFit = R.r(R.i:R.j);
    fill(axB, [rFit(1) rFit(end) rFit(end) rFit(1)], [-10 -10 10 10], cols{k}, 'FaceAlpha', alphas(k), 'EdgeColor', 'none', 'HandleVisibility', 'off');
    hB(k) = plot(axB, R.r, R.localSlope, marks{k}, 'Color', cols{k}, 'LineWidth', 1.2, 'MarkerSize', 3.2, 'MarkerFaceColor', cols{k});
    plot(axB, [rFit(1) rFit(end)], [R.D2 R.D2], '--', 'Color', cols{k}, 'LineWidth', 1.5, 'HandleVisibility', 'off');
    slopeValues = [slopeValues; R.localSlope(R.i:R.j)];
end
hold(axB, 'off');
yrange = max(max(slopeValues) - min(slopeValues), 0.05);
ylim(axB, [max(0, min(slopeValues) - 0.18*yrange), max(slopeValues) + 0.18*yrange]);
set(axB, 'XScale', 'log');
xlabel(axB, 'Scaling radius, $r$');
ylabel(axB, '$d\log C/d\log r$');
legend(axB, hB, {'$D_2(\beta_n)$', '$D_2([\beta_n,\beta_{n+1}])$'}, 'Location', 'best', 'Box', 'off', 'FontSize', 7);
title(axB, 'Transmission self-predictivity', 'FontWeight', 'normal', 'FontSize', 10);
text(axB, 0.04, 0.05, sprintf('$\\mathrm{GeoC}(\\beta_{n+1}\\mid\\beta_n)=%.3f$', geo_beta_self), ...
    'Units', 'normalized', 'FontSize', 8.5, 'VerticalAlignment', 'bottom');
addPanelLabel(axB, '(b)', -0.10, 1.04, 11);
styleMainAxis(axB);

axC = nexttile(tl, 3);
contourf(axC, invOut.MU, invOut.BETA, invOut.invariantDensity, 25, 'LineColor', 'none');
colormap(axC, batlow(256));
hold(axC, 'on');
nOverlay = min(800, numel(Mu));
plot(axC, Mu(1:nOverlay), Beta(1:nOverlay), '.', 'Color', [1 1 1], 'MarkerSize', 1.5);
hold(axC, 'off');
xlabel(axC, 'Virulence, $\mu$');
ylabel(axC, 'Transmission, $\beta$');
xlim(axC, [0 1]); ylim(axC, [0 max(Beta)]);
title(axC, 'Joint invariant density', 'FontWeight', 'normal', 'FontSize', 10);
cb = colorbar(axC);
cb.Label.String = '$p^*(\mu,\beta)$'; cb.Label.Interpreter = 'latex';
cb.TickLabelInterpreter = 'latex'; cb.FontSize = 7.5;
addPanelLabel(axC, '(c)', -0.10, 1.04, 11);
styleMainAxis(axC);

axD = nexttile(tl, 4);
hold(axD, 'on');
yyaxis(axD, 'left');
plot(axD, invOut.muVec, invOut.f_mu_marginal, '-', 'Color', [0.00 0.32 0.58], 'LineWidth', 1.8);
ylabel(axD, '$p_\mu^*(\mu)$');
yyaxis(axD, 'right');
plot(axD, invOut.betaVec, invOut.f_beta_marginal, '-', 'Color', [0.55 0.25 0.05], 'LineWidth', 1.8);
ylabel(axD, '$p_\beta^*(\beta)$');
xlabel(axD, 'Trait value');
hold(axD, 'off');
title(axD, 'Marginal invariant densities', 'FontWeight', 'normal', 'FontSize', 10);
addPanelLabel(axD, '(d)', -0.10, 1.04, 11);
styleMainAxis(axD);

exportgraphics(fig, fullfile(outDir, 'Figure_Case1c_Overview.png'), 'Resolution', 600);
close(fig);

%%
p_est = max(interp1(invOut.muVec, invOut.f_mu_marginal, x_grid, 'linear', 'extrap'), 0);
p_est = p_est ./ trapz(x_grid, p_est);
L1_error = trapz(x_grid, abs(p_est - p_exact));
fprintf('L1 error between analytical and estimated virulence density = %.6f\n', L1_error);
GeoCSummary = table(geo_mu_self, geo_mu_cond, geo_beta_self, geo_beta_cond, geo_beta_to_mu, geo_mu_to_beta, L1_error, ...
    'VariableNames', {'GeoC_mu_self','GeoC_mu_conditioned','GeoC_beta_self','GeoC_beta_conditioned', ...
                      'GeoC_beta_to_mu','GeoC_mu_to_beta','L1_density_error'});
writetable(GeoCSummary, fullfile(outDir, 'Case1c_GeoC_summary.csv'));

function styleMainAxis(ax)
set(ax, 'FontName', 'Helvetica', 'FontSize', 8.5, 'LineWidth', 0.75, 'TickDir', 'out', 'Box', 'off', 'Layer', 'top', ...
    'TickLabelInterpreter', 'latex', 'XMinorTick', 'off', 'YMinorTick', 'off', 'GridColor', [0.88 0.88 0.88], 'GridAlpha', 0.6);
end
